import java.util.*;import java.util.zip.*;import java.nio.file.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import org.objectweb.asm.tree.analysis.*;
public class Patch implements Opcodes {public static void main(String[] args)throws Exception{Map<String,byte[]> data=new TreeMap<>();int guards=0,visible=0;try(ZipFile z=new ZipFile(args[0])){for(ZipEntry entry:Collections.list(z.entries())){byte[] b=z.getInputStream(entry).readAllBytes();if(entry.getName().endsWith("/MinecraftClientMixin.class")||entry.getName().endsWith("/compat/SodiumCompat.class")){ClassNode c=new ClassNode();new ClassReader(b).accept(c,0);for(MethodNode m:c.methods){if(m.name.equals("tickXIVHEAD"))for(AbstractInsnNode i:m.instructions.toArray())if(i instanceof MethodInsnNode call&&call.owner.equals("dev/zomboid/isotacz/NativeActions")&&call.name.equals("nativeInput")){AbstractInsnNode branch=i.getNext();AbstractInsnNode ret=branch.getNext();if(branch.getOpcode()!=IFEQ||ret.getOpcode()!=RETURN)throw new IllegalStateException("Native guard shape changed");m.instructions.insertBefore(ret,new MethodInsnNode(INVOKESTATIC,"dev/zomboid/isotacz/VehicleView","nativeTick","()V",false));guards++;}if(c.name.endsWith("/SodiumCompat")&&m.name.equals("run")){m.instructions.insert(new MethodInsnNode(INVOKESTATIC,"dev/zomboid/isotacz/VehicleView","keepVisible","()V",false));visible++;}}ClassWriter w=new ClassWriter(ClassWriter.COMPUTE_MAXS);c.accept(w);b=w.toByteArray();}data.put(entry.getName(),b);}}if(guards!=1||visible!=1)throw new IllegalStateException("Missing view hooks: "+guards+" "+visible);try(var files=Files.walk(Path.of(args[2]))){for(Path f:files.filter(Files::isRegularFile).toList())data.put(Path.of(args[2]).relativize(f).toString(),Files.readAllBytes(f));}data.put("META-INF/neoforge.mods.toml",new String(data.get("META-INF/neoforge.mods.toml")).replace("3.6.2+zomboid.19","3.6.2+zomboid.20").getBytes());int methods=0;for(var e:data.entrySet())if(e.getKey().endsWith(".class")){ClassNode c=new ClassNode();new ClassReader(e.getValue()).accept(c,0);for(MethodNode m:c.methods)if((m.access&(ACC_ABSTRACT|ACC_NATIVE))==0){new Analyzer<>(new BasicVerifier()).analyze(c.name,m);methods++;}}try(ZipOutputStream z=new ZipOutputStream(Files.newOutputStream(Path.of(args[1])))){for(var e:data.entrySet()){z.putNextEntry(new ZipEntry(e.getKey()));z.write(e.getValue());z.closeEntry();}}System.out.println("Isometric view methods checked: "+methods);}}
